CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(254), phone VARCHAR(30), password_hash TEXT NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','SUSPENDED','LOCKED')), must_change_password BOOLEAN NOT NULL DEFAULT false, last_login_at TIMESTAMPTZ, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_org_email_unique ON users(organization_id,lower(email)) WHERE email IS NOT NULL; CREATE INDEX users_org_status_idx ON users(organization_id,status);
